from lib import *
S = SS('f64')
R = J('f64'); nc, rd = R['ratio']; g = R['gun']; fl_ = R['files']
steps = [
    step(f"没有字节码缓存:一个新进程里首次渲染 300 个模板(每个 15 行,含循环、过滤器、条件),第一个模板要 {R['nocache'][0][0]:.2f} ms,300 个共约 {nc:.0f} ms(3 次运行 {R['nocache'][0][1]:.0f}、{R['nocache'][1][1]:.0f}、{R['nocache'][2][1]:.0f} ms)。每个新进程都要把所有模板重新编译一遍。", t=tl(S(1)), done=lidx(S(1), '第一个模板'), kv=KV([['第一个模板', f"{R['nocache'][0][0]:.2f} ms"], ['300 个模板', f'约 {nc:.0f} ms']], ['300 个模板'])),
    step(f"FileSystemBytecodeCache:第一次(缓存目录是空的,编译并写入)第一个 {R['write'][0]:.2f} ms、300 个共 {R['write'][1]:.0f} ms;缓存目录里生成了 {fl_[0]} 个文件(文件名形如 {fl_[1][:28]}…,单个约 {fl_[2]} 字节,总计约 {fl_[3] / 1024:.0f} KiB)。之后的新进程直接读缓存:第一个 {R['read'][0][0]:.2f} ms,300 个共约 {rd:.1f} ms,比无缓存快 {nc / rd:.1f} 倍。", t=tl(S(2)), done=lidx(S(2), '第一次(缓存目录是空的', '缓存目录里生成了'), mark=lidx(S(2), '之后的新进程', '300 个模板:无缓存中位数'), b=bars([['无缓存', nc, f'{nc:.0f} ms'], ['读缓存', rd, f'{rd:.1f} ms']], nc, done=[0, 1]), kv=KV([['无缓存', f'{nc:.0f} ms'], ['读缓存', f'{rd:.1f} ms'], ['倍数', f'≈{nc / rd:.1f}']], ['倍数'])),
    step(f"源码变了之后缓存按源码校验和失效:修改 page0.html 后加载 page0 与 page1,缓存目录里被重写的文件数是 {R['invalidate']}(只有被修改的那个重新编译,没变的继续用缓存)。", t=tl(S(3)), done=lidx(S(3), '修改 page0.html'), kv=KV([['修改 1 个模板', '只重写 1 个缓存文件']], ['修改 1 个模板'])),
    step(f"在 Flask 里启用:app.jinja_env.bytecode_cache = FileSystemBytecodeCache(目录)(要在第一次渲染之前设)。渲染一个模板后缓存目录里出现 {R['flask']} 个文件。", t=tl(S(4)), done=lidx(S(4), 'Flask 渲染一个模板后'), kv=KV([['设置位置', 'jinja_env.bytecode_cache']], ['设置位置'])),
    step(f"真实 gunicorn(单 worker):新启动的服务器上头 60 个不同页面的请求共耗时:无缓存 {g['无缓存']:.0f} ms;有磁盘缓存但第一次启动(写入){g['有磁盘缓存(首次启动,写入)']:.0f} ms(多了写缓存的开销);同一个缓存目录再次启动(读取){g['有磁盘缓存(再次启动,读取)']:.0f} ms,约快 {g['无缓存'] / g['有磁盘缓存(再次启动,读取)']:.1f} 倍。重启或扩容(新 worker 启动)后的第一批请求最受益。", t=tl(S(5)), b=bars([['无缓存', g['无缓存'], f"{g['无缓存']:.0f} ms"], ['首次启动(写入)', g['有磁盘缓存(首次启动,写入)'], f"{g['有磁盘缓存(首次启动,写入)']:.0f} ms"], ['再次启动(读取)', g['有磁盘缓存(再次启动,读取)'], f"{g['有磁盘缓存(再次启动,读取)']:.0f} ms"]], g['有磁盘缓存(首次启动,写入)'], done=[0, 1, 2]), kv=KV([['无缓存', f"{g['无缓存']:.0f} ms"], ['首次(写入)', f"{g['有磁盘缓存(首次启动,写入)']:.0f} ms"], ['再次(读取)', f"{g['有磁盘缓存(再次启动,读取)']:.0f} ms"]], ['再次(读取)'])),
]
A = mkartf('f64', 64, 'Flask,Jinja2,Bytecode Cache,启动速度,真实验证,动画演示',
    f'实测 Jinja2 的磁盘字节码缓存:300 个模板在新进程里首次渲染从约 {nc:.0f} ms 降到 {rd:.1f} ms(快 {nc / rd:.1f} 倍);缓存目录 {fl_[0]} 个文件约 {fl_[3] / 1024:.0f} KiB;按源码校验和失效;Flask 里设 jinja_env.bytecode_cache;gunicorn 重启后头 60 个页面 {g["无缓存"]:.0f} ms → {g["有磁盘缓存(再次启动,读取)"]:.0f} ms。',
    '内存里的模板缓存在每次重启后都是空的,第一批请求要把用到的模板重新编译一遍。能不能把编译结果存到磁盘?效果多大?什么时候失效?这篇用 300 个模板和真实的 gunicorn 重启来量。',
    [(f'{nc / rd:.1f}×', '300 个模板在新进程里首次渲染:有字节码缓存相对没有的加速'), (f'{fl_[0]} 个', '300 个模板对应的缓存文件数(每个模板一个)'), ('1 个', '修改 1 个模板后被重写的缓存文件数')],
    [('没有缓存的启动', '<p>上一篇:<a href="flask-template-cache.html">模板缓存</a>;下一篇:<a href="flask-template-function-call-cost.html">模板中执行函数的性能问题</a>。</p>'), ('FileSystemBytecodeCache', None), ('失效规则', None), ('在 Flask 里启用', None), ('重启后的第一批请求', None)],
    steps, [ENV_F, '没有验证:缓存目录在多个 worker 同时首次启动时的并发写入、容器只读文件系统下的缓存目录选择、MemcachedBytecodeCache、Jinja 版本升级后旧缓存文件的兼容(文件名含校验和,没有专门验证版本隔离)'], '字节码缓存')
